#' Diagnostic Accuracy
#'
#' 
#' @param data .
#' @param reference .
#' @param test .
#' @param referencePositive .
#' @param testPositive .
#' @param ciWidth .
#' @param usePrevalence .
#' @param prevalence .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$accuracy} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ratios} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$population} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$counts$asDF}
#'
#' \code{as.data.frame(results$counts)}
#'
#' @export
pydecision <- function(
    data,
    reference = NULL,
    test = NULL,
    referencePositive,
    testPositive,
    ciWidth = 95,
    usePrevalence = FALSE,
    prevalence = 0.3,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydecision requires jmvcore to be installed (restart may be required)")

    if ( ! missing(reference)) reference <- jmvcore::resolveQuo(jmvcore::enquo(reference))
    if ( ! missing(test)) test <- jmvcore::resolveQuo(jmvcore::enquo(test))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(reference), reference, NULL),
            `if`( ! missing(test), test, NULL))

    for (v in reference) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in test) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pydecisionOptions$new(
        reference = reference,
        test = test,
        referencePositive = referencePositive,
        testPositive = testPositive,
        ciWidth = ciWidth,
        usePrevalence = usePrevalence,
        prevalence = prevalence,
        showConsole = showConsole)

    analysis <- pydecisionClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

